Ext._define('rh.modelreport.pdf.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.modelreport.pdf.Window',

    configOrderToolBar: ['add', 'edit', 'remove', 'pdf', '-', 'search'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Descricao', dataIndex: 'unicode',hidden: true},
                    {header: 'Nome', dataIndex: 'name',id: 'autoExpandColumn'},
                    {header: 'Modelo PDF', dataIndex: 'template_unicode', width: 120,hidden: true}
                ]
            );

        return this._columnModel;
    },

    getPdfAction:function(){
        return{
            text: 'Gerar Modelo',
            scope: this,
            iconCls: true,
            icon: '/' + global.Context + '/static/rh/images/relatorios.png',
            handler: function () {
                if (this.getSelectionModel().getSelected()){
                    selected = this.getSelectionModel().getSelected()
                    this.OpenWindow(selected)
                }else
                    Ext.Msg.show({
                        msg: 'Primeiro selecione um modelo',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    })
           
            }
        }
    },

    defaultClickFunction: function() {
        selected = this.getSelectionModel().getSelected()
        if(selected) this.OpenWindow(selected);
    },


    OpenWindow:function(selected){
        Ext._create('rh.modelreport.pdf.ReportWindow', {
            scope: this,
            selected: selected,
            closable: true,
        }).show();
    },


});

core.RestfulGrid.register(
    'rh.modelreport.pdf.Restful',
    'rh.modelreport.pdf.Grid'
);

